@app.template_global()
def versioned_static(filename: str) -> str:
    """Invalidate browser/CDN caches whenever a first-party asset changes."""
    asset = APP_DIR / "static" / filename
    version = hashlib.sha256(asset.read_bytes()).hexdigest()[:12]
    return url_for("static", filename=filename, v=version)

# ── In-process page cache ────────────────────────────────────────────────────
# Caches fully rendered HTML for static public GET pages.
# TTL = 10 min; invalidated on process restart (deploy).
_PAGE_CACHE: dict[str, tuple[bytes, str, float]] = {}  # path -> (body, content_type, ts)
_PAGE_CACHE_LOCK = threading.Lock()
_PAGE_CACHE_TTL = 600  # seconds

# Paths that must NOT be cached (dynamic / admin / API)
_CACHE_SKIP_PREFIXES = ("/admin", "/api", "/auth", "/ping", "/db-check",
                        "/tools/", "/ru/tools/")


def _cache_eligible(path: str) -> bool:
    if any(path.startswith(p) for p in _CACHE_SKIP_PREFIXES):
        return False
    return True


def _is_local_request() -> bool:
    """Never cache pages while the site is being edited on localhost."""
    return request.host.split(":", 1)[0] == "127.0.0.1"


@app.before_request
def _serve_from_cache():
    # Canonical-host redirects must happen before cache lookup. Otherwise a
    # warmed www response can be served as a 200 from the apex host.
    host = request.host.split(":")[0]
    if host == "marharuta.online":
        url = request.url.replace(f"{request.scheme}://marharuta.online", "https://www.marharuta.online", 1)
        return redirect(url, 301)
    if app.debug or _is_local_request():
        return None
    if request.method != "GET":
        return None
    # Query-aware routes (for example /blog/?page=2) must reach their view.
    # Caching only the path would otherwise mix distinct requests.
    if request.query_string:
        return None
    path = request.path
    if not _cache_eligible(path):
        return None
    with _PAGE_CACHE_LOCK:
        entry = _PAGE_CACHE.get(path)
    if entry is None:
        return None
    body, ct, ts = entry
    if time.monotonic() - ts > _PAGE_CACHE_TTL:
        with _PAGE_CACHE_LOCK:
            _PAGE_CACHE.pop(path, None)
        return None
    resp = make_response(body)
    resp.content_type = ct
    resp.headers["Cache-Control"] = "public, max-age=600, stale-while-revalidate=3600"
    resp.headers["X-Cache"] = "HIT"
    resp.headers["Age"] = str(max(0, int(time.monotonic() - ts)))
    return resp


@app.after_request
def _store_in_cache_and_add_headers(response: Response) -> Response:
    path = request.path
    response.headers.setdefault("X-Content-Type-Options", "nosniff")
    response.headers.setdefault("Referrer-Policy", "strict-origin-when-cross-origin")
    response.headers.setdefault("Permissions-Policy", "camera=(), microphone=(), geolocation=()")
    response.headers.setdefault("X-Frame-Options", "DENY")
    response.headers.setdefault("Strict-Transport-Security", "max-age=31536000; includeSubDomains")
    response.headers.setdefault(
        "Content-Security-Policy",
        "default-src 'self'; "
        "script-src 'self' 'unsafe-inline' https://www.googletagmanager.com; "
        "style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; "
        "font-src 'self' https://fonts.gstatic.com; "
        "img-src 'self' data: https://flagcdn.com https://www.google-analytics.com; "
        "connect-src 'self' https:; "
        "object-src 'none'; base-uri 'self'; frame-ancestors 'none'; form-action 'self'",
    )
    if app.debug or _is_local_request():
        # Live local design work must not mix new templates with stale assets.
        # Production keeps its normal page and versioned asset caches.
        response.headers["Cache-Control"] = "no-store"
        response.headers.pop("X-Cache", None)
        response.headers.pop("Age", None)
        return response
    if path.startswith("/static/") and response.status_code == 200:
        response.headers["Cache-Control"] = "public, max-age=604800"
    # Add Cache-Control to all public 200 GET responses
    if request.method == "GET" and response.status_code == 200:
        if _cache_eligible(path) and not request.query_string:
            response.headers.setdefault(
                "Cache-Control", "public, max-age=600, stale-while-revalidate=3600"
            )
            # Store in cache only for HTML pages
            ct = response.content_type or ""
            if "text/html" in ct and response.is_sequence and response.headers.get("X-Cache") != "HIT":
                body = response.get_data()
                with _PAGE_CACHE_LOCK:
                    _PAGE_CACHE[path] = (body, ct, time.monotonic())
    return response

