def ru_country_display(slug: str) -> str:
    forms = COUNTRY_FORMS_RU.get(slug)
    return forms[0] if forms else COUNTRY_EN_NAMES.get(slug, slug.replace("move-to-", "").replace("-", " ").title())


def ru_country_accusative(slug: str) -> str:
    forms = COUNTRY_FORMS_RU.get(slug)
    return forms[1] if forms else ru_country_display(slug)


def ru_country_destination(slug: str) -> str:
    special = {
        "move-to-bali": "на Бали",
        "move-to-vietnam": "во Вьетнам",
        "move-to-taiwan": "на Тайвань",
        "move-to-philippines": "на Филиппины",
        "move-to-sri-lanka": "на Шри-Ланку",
        "move-to-maldives": "на Мальдивы",
    }
    return special.get(slug, f"в {ru_country_accusative(slug)}")


def ru_country_prep(slug: str) -> str:
    forms = COUNTRY_FORMS_RU.get(slug)
    return forms[2] if forms else ru_country_display(slug)


def compact_number(value) -> str:
    if value is None:
        return "нет данных"
    try:
        value = float(value)
    except (TypeError, ValueError):
        return str(value)
    if value >= 1_000_000:
        return f"{value / 1_000_000:.1f} млн".replace(".0", "")
    if value >= 1_000:
        return f"{value / 1_000:.0f} тыс."
    return f"{value:.0f}"


def compact_number_en(value) -> str:
    if value is None:
        return "N/A"
    try:
        value = float(value)
    except (TypeError, ValueError):
        return str(value)
    if value >= 1_000_000:
        return f"{value / 1_000_000:.1f}M".replace(".0M", "M")
    if value >= 1_000:
        return f"{value / 1_000:.0f}K"
    return f"{value:.0f}"

