def breadcrumb_schema(items: list[tuple[str, str]], current_title: str, current_path: str) -> dict:
    is_ru = current_path.startswith("/ru/")
    schema_items = [("Главная" if is_ru else "Home", "/ru/" if is_ru else "/"), *items, (strip_html(current_title), current_path)]
    return {
        "@context": "https://schema.org",
        "@type": "BreadcrumbList",
        "itemListElement": [
            {
                "@type": "ListItem",
                "position": index,
                "name": name,
                "item": absolute_url(url),
            }
            for index, (name, url) in enumerate(schema_items, start=1)
        ],
    }


def organization_schema() -> dict:
    return {
        "@context": "https://schema.org",
        "@type": "Organization",
        "name": SITE_NAME,
        "url": SITE_URL,
        "logo": absolute_url(FAVICON_PATH),
        "email": CONTACT_EMAIL,
        "publishingPrinciples": absolute_url("/editorial-policy/"),
        "contactPoint": {
            "@type": "ContactPoint",
            "contactType": "editorial corrections",
            "email": CONTACT_EMAIL,
            "availableLanguage": ["English", "Russian"],
        },
    }


def editorial_team_schema(lang: str = "en") -> dict:
    return {
        "@type": "Organization",
        "name": DEFAULT_AUTHOR,
        "url": absolute_url(EDITORIAL_TEAM_URL if lang == "en" else "/ru/authors/editorial-team/"),
        "description": (
            "Editorial team checking relocation, visa and cost guides against official public sources."
            if lang == "en"
            else "Редакционная команда, которая сверяет визовые, страновые и бюджетные материалы с официальными источниками."
        ),
    }


def margarita_author_schema(lang: str = "en") -> dict:
    is_ru = lang == "ru"
    path = f"/ru/authors/{MARGARITA_AUTHOR_SLUG}/" if is_ru else f"/authors/{MARGARITA_AUTHOR_SLUG}/"
    return {
        "@context": "https://schema.org",
        "@type": "Person",
        "name": MARGARITA_AUTHOR_NAME_RU if is_ru else MARGARITA_AUTHOR_NAME_EN,
        "alternateName": MARGARITA_AUTHOR_NAME_EN if is_ru else MARGARITA_AUTHOR_NAME_RU,
        "url": absolute_url(path),
        "image": absolute_url(OG_MARGARITA_AUTHOR),
        "jobTitle": "Автор и редактор Relocate to Asia" if is_ru else "Author and Editor at Relocate to Asia",
        "description": (
            "Автор и редактор материалов о релокации в Азию с опытом жизни и путешествий более чем в 15 странах."
            if is_ru
            else "Relocation author and editor with first-hand living and travel experience across more than 15 countries."
        ),
        "sameAs": [MARGARITA_LINKEDIN_URL, MARGARITA_PROFILE_SOURCE_URL],
        "knowsAbout": ["relocation", "living abroad", "editorial review", "content management", "SEO content", "translation"],
        "alumniOf": {"@type": "CollegeOrUniversity", "name": "Luhansk Taras Shevchenko National University"},
        "worksFor": {"@type": "Organization", "name": SITE_NAME, "url": SITE_URL},
    }


def embedded_margarita_author_schema(lang: str = "en") -> dict:
    schema = dict(margarita_author_schema(lang))
    schema.pop("@context", None)
    return schema


def website_schema() -> dict:
    return {
        "@context": "https://schema.org",
        "@type": "WebSite",
        "name": SITE_NAME,
        "url": SITE_URL,
        "inLanguage": ["en", "ru"],
    }


def faq_schema_from_html(content: str | None, *, lang: str) -> dict | None:
    if not content:
        return None
    items: list[tuple[str, str]] = []
    for _quote, question, answer in re.findall(
        r'<div[^>]+class=(["\'])(?:[^"\']*\s)?(?:faq-item|rta-depth-faq-item)(?:\s[^"\']*)?\1[^>]*>\s*<h3\b[^>]*>(.*?)</h3>\s*<p\b[^>]*>(.*?)</p>\s*</div>',
        content,
        flags=re.IGNORECASE | re.DOTALL,
    ):
        items.append((strip_html(question), strip_html(answer)))
    for question, answer in re.findall(
        r'<details\b[^>]*>\s*<summary\b[^>]*>(.*?)</summary>\s*<p\b[^>]*>(.*?)</p>\s*</details>',
        content,
        flags=re.IGNORECASE | re.DOTALL,
    ):
        items.append((strip_html(question), strip_html(answer)))
    if not items:
        return None
    return {
        "@context": "https://schema.org",
        "@type": "FAQPage",
        "inLanguage": lang,
        "mainEntity": [
            {
                "@type": "Question",
                "name": question,
                "acceptedAnswer": {"@type": "Answer", "text": answer},
            }
            for question, answer in items[:8]
            if question and answer
        ],
    }


def item_list_schema(name: str, links: list[dict[str, str]]) -> dict | None:
    if not links:
        return None
    return {
        "@context": "https://schema.org",
        "@type": "ItemList",
        "name": name,
        "itemListElement": [
            {"@type": "ListItem", "position": index, "name": strip_html(link["title"]), "url": absolute_url(link["url"])}
            for index, link in enumerate(links, start=1)
        ],
    }


def web_application_schema(name: str, path: str, description: str) -> dict:
    return {
        "@context": "https://schema.org",
        "@type": "WebApplication",
        "name": strip_html(name),
        "url": absolute_url(path),
        "applicationCategory": "TravelApplication",
        "operatingSystem": "Web",
        "description": trim_text(strip_html(description), 200),
        "offers": {"@type": "Offer", "price": "0", "priceCurrency": "USD"},
    }


def trust_page_schema(title: str, path: str, *, page_type: str = "WebPage") -> dict:
    return {
        "@context": "https://schema.org",
        "@type": page_type,
        "name": strip_html(title),
        "url": absolute_url(path),
        "publisher": organization_schema(),
        "author": editorial_team_schema("ru" if path.startswith("/ru/") else "en"),
        "reviewedBy": editorial_team_schema("ru" if path.startswith("/ru/") else "en"),
        "dateModified": "2026-05-13",
        "publishingPrinciples": absolute_url("/ru/editorial-policy/" if path.startswith("/ru/") else "/editorial-policy/"),
        "isPartOf": {"@type": "WebSite", "name": SITE_NAME, "url": SITE_URL},
    }


