def country_facts_for_display(facts: sqlite3.Row | dict | None, slug: str, lang: str) -> dict | sqlite3.Row | None:
    if not facts or lang != "ru":
        return facts
    data = dict(facts)
    data.update(RU_COUNTRY_FACT_VALUES.get(slug, {}))
    return data


