def sitemap_paths() -> list[tuple[str, str]]:
    en_post_count = one("SELECT COUNT(*) AS count FROM posts WHERE lang = 'en'")["count"]
    ru_post_count = one("SELECT COUNT(*) AS count FROM posts WHERE lang = 'ru'")["count"]
    per_page = 10
    paths: list[tuple[str, str]] = [
        ("/", "daily"),
        ("/ru/", "daily"),
        ("/countries/", "weekly"),
        ("/ru/countries/", "weekly"),
        ("/tools/", "monthly"),
        ("/ru/tools/", "monthly"),
        ("/compare/", "weekly"),
        ("/ru/compare/", "weekly"),
        ("/compare-cities/", "monthly"),
        ("/ru/compare-cities/", "monthly"),
        ("/visas/", "weekly"),
        ("/ru/visas/", "weekly"),
        ("/best-countries-in-asia-to-move/", "monthly"),
        ("/ru/best-countries-in-asia-to-move/", "monthly"),
        ("/cheapest-countries-in-asia/", "monthly"),
        ("/ru/cheapest-countries-in-asia/", "monthly"),
        ("/move-to-asia/", "monthly"),
        ("/ru/move-to-asia/", "monthly"),
        ("/digital-nomad-visas-asia/", "monthly"),
        ("/ru/digital-nomad-visas-asia/", "monthly"),
        ("/retire-in-asia/", "monthly"),
        ("/ru/retire-in-asia/", "monthly"),
        ("/cost-of-living-asia/", "monthly"),
        ("/ru/cost-of-living-asia/", "monthly"),
        ("/guides/", "weekly"),
        ("/ru/guides/", "weekly"),
        ("/blog/", "daily"),
        ("/ru/blog/", "daily"),
        ("/about/", "monthly"),
        ("/ru/about/", "monthly"),
        ("/authors/", "monthly"),
        ("/ru/authors/", "monthly"),
        ("/authors/editorial-team/", "monthly"),
        ("/ru/authors/editorial-team/", "monthly"),
        ("/authors/margarita-yarovenko/", "monthly"),
        ("/ru/authors/margarita-yarovenko/", "monthly"),
        ("/contact/", "monthly"),
        ("/ru/contact/", "monthly"),
        ("/editorial-policy/", "monthly"),
        ("/ru/editorial-policy/", "monthly"),
        ("/how-we-verify-data/", "monthly"),
        ("/ru/how-we-verify-data/", "monthly"),
    ]
    for page_num in range(2, max((en_post_count + per_page - 1) // per_page, 1) + 1):
        paths.append((f"/blog/page/{page_num}/", "daily"))
    for page_num in range(2, max((ru_post_count + per_page - 1) // per_page, 1) + 1):
        paths.append((f"/ru/blog/page/{page_num}/", "daily"))
    for row in many("SELECT link FROM pages WHERE link IS NOT NULL AND link != ''"):
        link = row["link"]
        if link.startswith(SITE_URL):
            link = link.removeprefix(SITE_URL) or "/"
        paths.append((link, "monthly"))
    for row in many("SELECT slug, lang FROM posts ORDER BY date DESC"):
        prefix = "/blog" if row["lang"] == "en" else "/ru/blog"
        paths.append((f"{prefix}/{row['slug']}/", "weekly"))
    seen = set()
    unique: list[tuple[str, str]] = []
    for path, changefreq in paths:
        if path not in seen:
            seen.add(path)
            unique.append((path, changefreq))
    return unique


@app.route("/sitemap.xml")
def sitemap_xml():
    from html import escape
    from datetime import datetime, timezone

    alternate_map = post_pair_map()
    alternate_map.update(compare_pair_map())
    alternate_map["/blog/"] = [
        {"lang": "en", "url": absolute_url("/blog/")},
        {"lang": "ru", "url": absolute_url("/ru/blog/")},
        {"lang": "x-default", "url": absolute_url("/blog/")},
    ]
    alternate_map["/ru/blog/"] = alternate_map["/blog/"]
    en_post_count = one("SELECT COUNT(*) AS count FROM posts WHERE lang = 'en'")["count"]
    ru_post_count = one("SELECT COUNT(*) AS count FROM posts WHERE lang = 'ru'")["count"]
    per_page = 10
    total_paginated = max(
        max((en_post_count + per_page - 1) // per_page, 1),
        max((ru_post_count + per_page - 1) // per_page, 1),
    )
    for page_num in range(2, total_paginated + 1):
        alternates = blog_page_alternates(
            page_num, counts={"en": en_post_count, "ru": ru_post_count},
        )
        for alternate in alternates:
            alternate_map[local_path(alternate["url"])] = alternates
    paths = sitemap_paths()
    seen_paths = {path for path, _ in paths}
    # Every localized URL advertised through hreflang must also be discoverable
    # as its own sitemap entry, including generated RU country/tool/guide pages.
    for path, changefreq in list(paths):
        alternates = alternate_map.get(path) or default_page_alternates(path) or []
        for item in alternates:
            alternate_path = local_path(item["url"])
            if alternate_path not in seen_paths:
                seen_paths.add(alternate_path)
                paths.append((alternate_path, changefreq))

    source_files = [Path(__file__), DB_PATH, APP_DIR / "templates" / "base.html"]
    latest_source_mtime = max(path.stat().st_mtime for path in source_files if path.exists())
    default_lastmod = datetime.fromtimestamp(latest_source_mtime, tz=timezone.utc).date().isoformat()

    urls = []
    for path, changefreq in paths:
        alternates = alternate_map.get(path) or default_page_alternates(path) or []
        links = "".join(
            f"<xhtml:link rel=\"alternate\" hreflang=\"{escape(item['lang'])}\" href=\"{escape(item['url'])}\" />"
            for item in alternates
        )
        lastmod = default_lastmod
        post_match = re.match(r"^/(?:ru/)?blog/([^/]+)/$", path)
        if post_match:
            post = one("SELECT date FROM posts WHERE slug = ? ORDER BY date DESC LIMIT 1", (post_match.group(1),))
            if post and post["date"]:
                lastmod = str(post["date"])[:10]
        urls.append(
            "  <url>"
            f"<loc>{escape(absolute_url(path))}</loc>"
            f"{links}"
            f"<lastmod>{escape(lastmod)}</lastmod>"
            f"<changefreq>{changefreq}</changefreq>"
            "</url>"
        )
    xml = '<?xml version="1.0" encoding="UTF-8"?>\n'
    xml += '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xhtml="http://www.w3.org/1999/xhtml">\n'
    xml += "\n".join(urls)
    xml += "\n</urlset>\n"
    return Response(xml, mimetype="application/xml")

@app.route("/robots.txt")
def robots_txt():
    body = "\n".join([
        "User-agent: *",
        "Allow: /",
        f"Sitemap: {SITE_URL}/sitemap.xml",
        "",
    ])
    return Response(body, mimetype="text/plain")


@app.errorhandler(404)
def not_found(error):
    """Return a crawlable, helpful 404 without creating a soft redirect."""
    lang = "ru" if request.path.startswith("/ru/") else "en"
    title = "Страница не найдена" if lang == "ru" else "Page not found"
    description = (
        "Запрошенная страница не найдена. Вернитесь на главную или выберите другой раздел."
        if lang == "ru"
        else "The requested page could not be found. Return home or browse another section."
    )
    seo = seo_payload(title=title, description=description, lang=lang, canonical_path=request.path)
    seo["meta_robots"] = "noindex,follow"
    return render_template("404.html", seo=seo, lang_code=lang), 404


@app.errorhandler(410)
def gone(error):
    """Retire unrelated legacy content with an explicit Gone response."""
    lang = "ru" if request.path.startswith(("/ru/", "/uk/")) else "en"
    title = "Страница удалена" if lang == "ru" else "Page removed"
    description = (
        "Эта страница относилась к прежней версии сайта и была окончательно удалена."
        if lang == "ru"
        else "This page belonged to a previous version of the site and has been permanently removed."
    )
    seo = seo_payload(title=title, description=description, lang=lang, canonical_path=request.path)
    seo["meta_robots"] = "noindex,follow"
    return render_template("404.html", seo=seo, lang_code=lang), 410


